async onEditingModeChange(editingMode) {
      if (this.isContentEditorActive && editingMode === EDITING_MODE_MARKDOWN_FIELD) {
        try {
          // The observer is debounced; read before unmounting the rich editor.
          const markdown = this.$refs.contentEditor.getSerializedContentForHandoff();
          if (typeof markdown !== 'string') throw new Error('Expected current Markdown.');
          this.updateMarkdownFromContentEditor({ markdown });
          if (this.alert?.handoffError) this.alert = null;
        } catch {
          this.alert = {
            message: s__(
              'MarkdownEditor|Unable to switch to Markdown. Your document is still open in the rich text editor. Finish the current edit or resolve the conversion error, then try again.',
            ),
            variant: 'danger',
            handoffError: true,
            dismiss: () => { this.alert = null; },
          };
          return;
        }
      }

      if (
        editingMode === EDITING_MODE_CONTENT_EDITOR &&
        this.beforeContentEditor &&
        !(await this.beforeContentEditor(this.markdown))
      ) {
        return;
      }

      this.editingMode = editingMode;
      this.notifyEditingModeChange(editingMode);
    }

onEditingModeRestored(editingMode) {
      if (!this.isDefaultEditorEnabled) return;
      if (this.isContentEditorActive && editingMode === EDITING_MODE_MARKDOWN_FIELD) {
        return this.onEditingModeChange(editingMode);
      }
      if (editingMode === EDITING_MODE_CONTENT_EDITOR && !this.enableContentEditor) {
        this.editingMode = EDITING_MODE_MARKDOWN_FIELD;
        return;
      }

      this.editingMode = editingMode;
      this.$emit(EDITING_MODE_EVENTS[editingMode]);
      this.notifyEditingModeChange(editingMode);
    }

getSerializedContentForHandoff() {
      if (
        this.isLoading ||
        !this.contentEditor?.tiptapEditor?.view ||
        this.contentEditor.tiptapEditor.view.composing ||
        (!this.collaborationProvider && this.latestMarkdown !== this.markdown)
      ) {
        throw new Error('The rich text editor is not ready for serialization.');
      }
      return this.contentEditor.getSerializedContent();
    }
